"""Placement helpers for KiCad 10 schematics generated by `pcb apply schematic`.

Plain stdlib. Import from a placement generator script:

    sys.path.insert(0, "<library>/tools/schematic")
    import place
    sh = place.Sheet.load("eda/INA.kicad_sch", namespace="circuit-blocks/INA")
    sh.clear()                                   # drop all wires, labels, junctions, no-connects
    sh.place_symbol("U1", 133.35, 129.54, rot=180)
    x, y = sh.pin_point("U1", "8")               # connection point of pin 8, KiCad transform applied
    sh.wire([(x, y), (x - 10.16, y)], "vbus")
    sh.hlabel("BUS_OUT", x - 10.16, y, direction=180, key="vbus")
    sh.save()

Conventions (verified against kicad-cli netlists, all 8 rotation/mirror cases)
- Sheet y axis points down; library (symbol) y axis points up. Angles are counter-clockwise as seen on screen.
- A placed symbol is `(at x y rot)` plus optional `(mirror x|y)`. Transform order: library pin position, y flipped to
  screen, rotated by `rot`, THEN mirrored (`mirror x` flips screen y, `mirror y` flips screen x), then translated.
- A library pin's `(at)` is its connection point; its angle points from the connection point into the symbol body, so
  wires arrive from the opposite side.
- `direction` arguments are screen angles: 0 = +x (right), 90 = up, 180 = left, 270 = down.
- Every emitter takes a `key`; the UUID is uuid5(namespace, kind + key), so re-runs write identical files and an
  emitter called twice with one key replaces the first item.
"""
import math
import re
import subprocess
import uuid

import kicad_sexpr as kx
from kicad_sexpr import Atom, Node, fmt, parse_snippet, qstr

GRID_FINE = 1.27
GRID = 2.54
FONT = 1.27
HEAD_FONT = 1.524

# KiCad paper keywords (verified in libkicommon of KiCad 10.0.1). Tabloid / Ledger = 11 x 17 in.
PAPER_A4, PAPER_A3 = "A4", "A3"
PAPER_TABLOID = "USLedger"
PAPER_LETTER = "USLetter"

SIDE_KINDS = ("wire", "junction", "no_connect", "label", "global_label", "hierarchical_label")


def snap(v, grid=GRID_FINE):
    """Nearest multiple of `grid` (default 1.27 mm), rounded to 4 decimals."""
    return round(round(v / grid) * grid, 4)


def pin_endpoint(pin_xy, at_xy, rot=0, mirror=None):
    """Sheet coordinates of a library pin connection point for a symbol placed at `at_xy`.

    pin_xy: the library `(at px py)` of the pin (y up). rot: 0/90/180/270. mirror: None, "x" or "y"."""
    vx, vy = _xform(pin_xy[0], -pin_xy[1], rot, mirror)
    return round(at_xy[0] + vx, 4), round(at_xy[1] + vy, 4)


def pin_direction(pin_angle, rot=0, mirror=None):
    """Screen angle (0/90/180/270) a pin points toward, i.e. from its connection point into the symbol body.
    A wire reaches the pin from the opposite side; text that must run away from the wire uses this direction."""
    a = math.radians(pin_angle)
    vx, vy = _xform(math.cos(a), -math.sin(a), rot, mirror)
    return int(round(math.degrees(math.atan2(-vy, vx)))) % 360


def _xform(vx, vy, rot, mirror):
    t = math.radians(rot)
    c, s = round(math.cos(t), 12), round(math.sin(t), 12)
    vx, vy = vx * c + vy * s, -vx * s + vy * c  # CCW on screen (y down)
    if mirror == "x":
        vy = -vy
    elif mirror == "y":
        vx = -vx
    return vx, vy


def _dir_vec(direction):
    a = math.radians(direction)
    return round(math.cos(a), 6), round(-math.sin(a), 6)


def label_style(direction, hier=False):
    """(angle, justify) for a label whose text must run toward `direction`.
    KiCad draws text left-to-right or bottom-to-top only: directions 0 and 90 use `left`, 180 and 270 `right`
    (text ends at the anchor). Local labels add `bottom` so the text sits above (or left of) its wire."""
    j = "left" if direction in (0, 90) else "right"
    return direction, j if hier else j + " bottom"


class Pin:
    def __init__(self, number, name, x, y, angle, hidden=False):
        self.number, self.name, self.x, self.y, self.angle, self.hidden = number, name, x, y, angle, hidden


class Symbol:
    """A placed symbol (top-level `(symbol ...)`)."""

    def __init__(self, node):
        self.node = node

    def _prop(self, name):
        for p in self.node.nodes("property"):
            if p.atoms()[1].value == name:
                return p

    @property
    def ref(self):
        return self._prop("Reference").atoms()[2].value

    @property
    def value(self):
        return self._prop("Value").atoms()[2].value

    @property
    def lib_id(self):
        return self.node.get("lib_id").args()[0]

    @property
    def unit(self):
        u = self.node.get("unit")
        return int(u.nums()[0]) if u else 1

    @property
    def at(self):
        return tuple(self.node.get("at").nums()[:2])

    @property
    def rot(self):
        n = self.node.get("at").nums()
        return int(n[2]) % 360 if len(n) > 2 else 0

    @property
    def mirror(self):
        m = self.node.get("mirror")
        return m.args()[0] if m else None


class Sheet:
    def __init__(self, root, namespace="sheet", path=None):
        self.root, self.path = root, path
        self.ns = uuid.uuid5(uuid.NAMESPACE_URL, namespace)

    @classmethod
    def load(cls, path, namespace="sheet"):
        return cls(kx.load(path), namespace, path)

    def save(self, path=None):
        kx.save(path or self.path, self.root)

    # ------------------------------------------------------------------ library pins and placed symbols
    def lib_symbol(self, lib_id):
        for s in self.root.get("lib_symbols").nodes("symbol"):
            if s.atoms()[1].value == lib_id:
                return s
        raise KeyError(lib_id)

    def lib_pins(self, lib_id, unit=1, body_style=1):
        """{pin number: Pin} for one unit (common unit 0 and body style 0 pins included). Library coordinates."""
        out = {}
        for sub in self.lib_symbol(lib_id).nodes("symbol"):
            m = re.match(r".*_(\d+)_(\d+)$", sub.atoms()[1].value)
            u, b = (int(m.group(1)), int(m.group(2))) if m else (0, 0)
            if u not in (0, unit) or b not in (0, body_style):
                continue
            for p in sub.nodes("pin"):
                at = p.get("at").nums()
                num, name = p.get("number").args()[0], p.get("name").args()[0]
                out[num] = Pin(num, name, at[0], at[1], at[2] if len(at) > 2 else 0, p.get("hide") is not None
                               and p.get("hide").args()[:1] == ["yes"])
        return out

    def symbols(self):
        return [Symbol(n) for n in self.root.nodes("symbol")]

    def symbol(self, ref):
        for s in self.symbols():
            if s.ref == ref:
                return s
        raise KeyError(ref)

    def pin_point(self, ref, number):
        """Connection point (x, y) of pin `number` of the placed symbol `ref`."""
        s = self.symbol(ref)
        p = self.lib_pins(s.lib_id, s.unit)[number]
        return pin_endpoint((p.x, p.y), s.at, s.rot, s.mirror)

    def pin_points(self, ref):
        s = self.symbol(ref)
        return {n: pin_endpoint((p.x, p.y), s.at, s.rot, s.mirror) for n, p in self.lib_pins(s.lib_id, s.unit).items()}

    def pin_dir(self, ref, number):
        s = self.symbol(ref)
        return pin_direction(self.lib_pins(s.lib_id, s.unit)[number].angle, s.rot, s.mirror)

    def place_symbol(self, ref, x, y, rot=None, mirror="keep"):
        """Move (and optionally rotate / mirror) a placed symbol. Its fields move with it (same offsets) and keep
        their visual text angle; use `set_field` for fields that must change side or angle. `mirror`: None clears it,
        "x"/"y" sets it, "keep" leaves it."""
        s = self.symbol(ref)
        ax, ay = s.at
        dx, dy = x - ax, y - ay
        at = s.node.get("at")
        old_rot = s.rot
        new_rot = old_rot if rot is None else rot % 360
        at.set_nums(x, y, new_rot)
        if mirror != "keep":
            m = s.node.get("mirror")
            if m:
                s.node.remove(m)
            if mirror:
                m = parse_snippet("(mirror %s)" % mirror)
                m.ws = "\n\t\t"
                s.node.items.insert(s.node.items.index(at) + 1, m)
        for p in s.node.nodes("property"):
            pa = p.get("at")
            n = pa.nums()
            # stored field angle is relative to the symbol rotation: keep the visual angle
            pa.set_nums(n[0] + dx, n[1] + dy, ((n[2] if len(n) > 2 else 0) + old_rot - new_rot) % 360)

    def set_field(self, ref, name, dx, dy, angle=0, justify=None):
        """Place a field (Reference, Value, ...) at offset (dx, dy) from the symbol origin, VISUAL text `angle` (0 or
        90; the file stores it relative to the symbol rotation, handled here), optional
        justify ("left", "right", "left bottom" ...). Sets do_not_autoplace so KiCad keeps it there."""
        s = self.symbol(ref)
        p = s._prop(name)
        p.get("at").set_nums(s.at[0] + dx, s.at[1] + dy, (angle - s.rot) % 360)
        dna = p.get("do_not_autoplace")
        if dna:
            dna.atoms()[1].raw = "yes"
        eff = p.get("effects")
        j = eff.get("justify")
        if j:
            eff.remove(j)
        if justify:
            n = parse_snippet("(justify %s)" % justify)
            eff.items.append(n)
            n.ws = "\n\t\t\t\t"
            eff.close_ws = "\n\t\t\t"

    def remove_symbol(self, ref):
        self.root.remove(self.symbol(ref).node)

    # ------------------------------------------------------------------ emitters
    def _uid(self, kind, key):
        return str(uuid.uuid5(self.ns, kind + ":" + key))

    def _add(self, text, kind, key):
        """Parse and append an item; an earlier item with the same uuid is removed first."""
        u = self._uid(kind, key)
        for n in self.root.nodes():
            g = n.get("uuid")
            if g and g.args()[0] == u:
                self.root.remove(n)
        node = parse_snippet(text.replace("@UUID@", u))
        self.root.append(node)
        return node

    def clear(self, kinds=SIDE_KINDS):
        """Remove all top-level items of these kinds (default: wiring and labels), e.g. before regenerating."""
        for n in self.root.nodes():
            if n.head in kinds:
                self.root.remove(n)

    def wire(self, pts, key):
        """Polyline as one wire per segment (keys key0, key1, ...); a two-point list is one wire keyed `key`."""
        segs = list(zip(pts, pts[1:]))
        for i, ((x1, y1), (x2, y2)) in enumerate(segs):
            self._add('(wire\n\t(pts\n\t\t(xy %s %s) (xy %s %s)\n\t)\n\t(stroke\n\t\t(width 0)\n\t\t(type default)\n\t)\n'
                      '\t(uuid "@UUID@")\n)' % (fmt(x1), fmt(y1), fmt(x2), fmt(y2)), "wire",
                      key if len(segs) == 1 else "%s%d" % (key, i))

    def junction(self, x, y, key):
        self._add('(junction\n\t(at %s %s)\n\t(diameter 0)\n\t(color 0 0 0 0)\n\t(uuid "@UUID@")\n)' % (fmt(x), fmt(y)),
                  "junction", key)

    def no_connect(self, x, y, key):
        self._add('(no_connect\n\t(at %s %s)\n\t(uuid "@UUID@")\n)' % (fmt(x), fmt(y)), "no_connect", key)

    def _eff(self, size, justify, bold=False):
        return ('\t(effects\n\t\t(font\n\t\t\t(size %s %s)%s\n\t\t)\n\t\t(justify %s)\n\t)\n'
                % (fmt(size), fmt(size), "\n\t\t\t(bold yes)" if bold else "", justify))

    def label(self, text, x, y, direction, key, size=FONT):
        """Local label. Anchor (x, y) on a wire; `direction` = way the text runs, normally along the wire from the
        anchor (the anchor sits at the wire end and the text lies on top of the wire, never beyond it)."""
        a, j = label_style(direction)
        self._add('(label %s\n\t(at %s %s %d)\n%s\t(uuid "@UUID@")\n)' % (qstr(text), fmt(x), fmt(y), a,
                                                                          self._eff(size, j)), "label", key)

    def hlabel(self, text, x, y, direction, key, shape="bidirectional", size=FONT):
        """Hierarchical label. Anchor on the wire END; `direction` = way the text runs, AWAY from the wire (the flag
        and text sit beyond the end of the wire)."""
        a, j = label_style(direction, hier=True)
        self._add('(hierarchical_label %s\n\t(shape %s)\n\t(at %s %s %d)\n%s\t(uuid "@UUID@")\n)'
                  % (qstr(text), shape, fmt(x), fmt(y), a, self._eff(size, j)), "hlabel", key)

    def global_label(self, text, x, y, direction, key, shape="bidirectional", size=FONT):
        """Global label; same anchor and direction rule as `hlabel`."""
        a, j = label_style(direction, hier=True)
        self._add('(global_label %s\n\t(shape %s)\n\t(at %s %s %d)\n%s\t(uuid "@UUID@")\n)'
                  % (qstr(text), shape, fmt(x), fmt(y), a, self._eff(size, j)), "glabel", key)

    def text(self, text, x, y, key, justify="left", size=FONT, bold=False):
        """Free text note; `\\n` in `text` starts a new line. (x, y) is the anchor for `justify`
        ("left", "left top", "left bottom", "right top" ...)."""
        self._add('(text %s\n\t(exclude_from_sim no)\n\t(at %s %s 0)\n%s\t(uuid "@UUID@")\n)'
                  % (qstr(text), fmt(x), fmt(y), self._eff(size, justify, bold)), "text", key)

    def rectangle(self, x1, y1, x2, y2, key, dashed=True):
        self._add('(rectangle\n\t(start %s %s)\n\t(end %s %s)\n\t(stroke\n\t\t(width 0.1524)\n\t\t(type %s)\n\t)\n'
                  '\t(fill\n\t\t(type none)\n\t)\n\t(uuid "@UUID@")\n)'
                  % (fmt(x1), fmt(y1), fmt(x2), fmt(y2), "dash" if dashed else "default"), "rect", key)

    def group_box(self, x1, y1, x2, y2, title, key, dashed=True):
        """Titled group box: dashed rectangle plus a bold title inside its top-left corner."""
        self.rectangle(x1, y1, x2, y2, key, dashed)
        self.text(title, x1 + 1.27, y1 + 1.27, key + ".title", "left top", HEAD_FONT, True)

    # ------------------------------------------------------------------ power symbols -> hierarchical labels
    def power_to_hlabels(self, shape="input"):
        """Local-rails recipe for a reusable child sheet: replace every power symbol (VCC, GND, ... a library symbol
        with a `(power ...)` flag) by a hierarchical label named after its Value, at the symbol's pin point, text
        running the way the pin points (up for a rail, down for ground). Returns the labels made."""
        made = []
        for s in self.symbols():
            ls = self.lib_symbol(s.lib_id)
            if ls.get("power") is None:
                continue
            pins = self.lib_pins(s.lib_id, s.unit)
            num = next(iter(pins))
            x, y = pin_endpoint((pins[num].x, pins[num].y), s.at, s.rot, s.mirror)
            d = pin_direction(pins[num].angle, s.rot, s.mirror)
            key = "pwr:%s:%s:%s" % (s.value, fmt(x), fmt(y))
            self.root.remove(s.node)
            self.hlabel(s.value, x, y, d, key, shape)
            made.append((s.value, x, y, d))
        return made

    # ------------------------------------------------------------------ paper and title block
    def set_paper(self, keyword, portrait=False):
        """Set the paper size, e.g. PAPER_TABLOID. Landscape unless portrait=True."""
        p = self.root.get("paper")
        for a in p.atoms()[1:]:
            p.items.remove(a)
        p.items.append(Atom(qstr(keyword)))
        if portrait:
            p.items.append(Atom("portrait"))

    def set_title_block(self, title=None, rev=None, date=None, company=None, comments=None):
        """Set title block fields; `comments` is {1: "...", 2: "..."} (KiCad has comment 1..9). Fields not given
        are left alone; the block is created after `(paper)` if missing. Each comment line appears once."""
        tb = self.root.get("title_block")
        if tb is None:
            tb = Node(ws="\n\t")
            tb.items.append(Atom("title_block", ""))
            self.root.items.insert(self.root.items.index(self.root.get("paper")) + 1, tb)
        fields = [("title", title), ("date", date), ("rev", rev), ("company", company)]
        for k, v in fields:
            if v is not None:
                self._tb_set(tb, k, [qstr(v)])
        for n, v in sorted((comments or {}).items()):
            self._tb_set(tb, "comment", [str(n), qstr(v)], match=str(n))

    @staticmethod
    def _tb_set(tb, head, vals, match=None):
        node = None
        for c in tb.nodes(head):
            if match is None or c.atoms()[1].raw == match:
                node = c
        if node is None:
            node = Node(ws="\n\t\t")
            node.items.append(Atom(head, ""))
            tb.items.append(node)
        node.items = node.items[:1] + [Atom(v) for v in vals]
        tb.close_ws = "\n\t"


def repo_comment(repo_dir, subdir=""):
    """'host/owner/repo @ shorthash' for a title block comment (from git; no network)."""
    def git(*a):
        return subprocess.run(["git", "-C", repo_dir, *a], capture_output=True, text=True).stdout.strip()
    url = re.sub(r"^(https?://|git@)", "", git("remote", "get-url", "origin")).replace(":", "/")
    url = re.sub(r"\.git$", "", url)
    return "%s @ %s%s" % (url, git("rev-parse", "--short", "HEAD"), (": " + subdir) if subdir else "")
